// People's names by culture: given names, family names and the conventions that join them.
//
// One namer serves a map's cultures. Every name comes from a seed (a person's, or a household's
// and a purpose), so the same seed always gives the same name and nothing need be stored; the
// shape is the place-name API's (a name per item from a seed), so the two can share it.
//
// Given names for the real-world bases come from our own lists, most common first, with a share
// generated by a chain trained on them (the "mix" method, the default); the invented bases are
// always generated, partly from stems of the culture's own place names. Family names are drawn by
// the culture's convention from its list, its trades, its places, features and fathers.
//
// Personal names N2, from the names prototype's `lib/names.mjs`: its streams are the kernel's
// (`Random`), so the names differ from N1's sample cards, which used a stream of their own.
import { NamesGenerator } from "../../../vendor/azgaar-names/names-generator.js";
import { FILRODENSWMB } from "../../config.js";
import { hashString, mulberry32 } from "../random/Random.js";
import { FAMOUS, FANTASY_BASES, REAL_BASES, TRADE_CONCEPT } from "./data/PersonNameBases.js";
import { feminineFamily, fill, patronymic } from "./NameConventions.js";
import { isBlockedName } from "./NameFilter.js";

export const METHODS = Object.freeze(["list", "chain", "mix", "stem"]);

/** Defaults that are the namer's, not a culture's (`FILRODENSWMB.PERSON_NAMES`). */
export const NAMES = FILRODENSWMB.PERSON_NAMES;

// Members named into the household's own line, and those who bring their own name
const OWN = new Set(["servant", "apprentice", "journeyman", "lodger", "miller's man"]);
const SEX_OF = { head: "m", "widow, head": "f", "widower, head": "m", wife: "f", husband: "m", mother: "f", father: "m", kinsman: "m", kinswoman: "f" };

const SINGLE_WORD = /^\p{Lu}[\p{Ll}\p{M}'’]*(-\p{L}[\p{Ll}\p{M}'’]*)?$/u;
const TRIPLE = /(.)\1\1/u;
const VOWEL = /[aeiouyàáâãäåæèéêëìíîïòóôõöøùúûüýāēīōūœ]/iu;

/**
 * A plain-text list the user typed (one name per line) made safe to use: control characters and
 * markup dropped, each line trimmed and checked to be a name (letters, marks, spaces, apostrophes,
 * hyphens and full stops), duplicates removed, the list capped.
 */
export function sanitiseList(text) {
    if (typeof text !== "string") return [];
    const seen = new Set();
    const out = [];
    for (const raw of text.normalize("NFC").split(/\r?\n/)) {
        const line = raw.replace(/[\p{Cc}\p{Cf}]/gu, "").replace(/\s+/gu, " ").trim();
        if (!line || line.length > NAMES.NAME_MAX) continue;
        if (!/^[\p{L}\p{M}][\p{L}\p{M}' ’.-]*$/u.test(line)) continue;
        if (seen.has(line)) continue;
        seen.add(line);
        out.push(line);
        if (out.length >= NAMES.LIST_MAX) break;
    }
    return out;
}

const split = (text) => (text ? text.split(",").map((s) => s.trim()).filter(Boolean) : []);

/** The lengths a generated name may take, from the list it was trained on. */
function lengthsOf(list) {
    const lengths = list.map((n) => n.length).sort((a, b) => a - b);
    if (!lengths.length) return [3, 9];
    const at = (q) => lengths[Math.min(lengths.length - 1, Math.floor(q * lengths.length))];
    return [Math.max(3, at(0.1)), Math.max(at(0.9) + 1, 5)];
}

/**
 * A namer for a map's cultures.
 * @param {object} options
 * @param {{name: string, nameBase?: string, names?: object}[]} options.cultures - Each culture's
 *     name base and its optional names settings: { form, order, lineage, wife, method, lists: {m,
 *     f, family} (the user's own, plain text), listUse: "as-is" | "train" }.
 * @param {"list"|"chain"|"mix"} [options.method] - The default method for real-world bases.
 * @param {string[]} [options.nearby] - Names of places on the map near the place being named
 *     (the local input's neighbours); a share of toponymic family names comes from them.
 */
export function createNamer({ cultures = [], method = "mix", nearby = [] } = {}) {
    const places = new NamesGenerator(() => 0);
    // Only whole names of one word: a castle's name with its keep word, or a name of several
    // words, would not read as a byname
    const near = [...new Set((Array.isArray(nearby) ? nearby : []).filter((n) => typeof n === "string" && /^\p{Lu}[\p{L}\p{M}'’]+$/u.test(n)))];
    const prepared = new Map();
    for (const culture of cultures) prepared.set(culture.name, prepare(culture, method, places, near));
    const fallback = prepare({ name: "", nameBase: "Human Generic" }, method, places, near);
    const cultureOf = (name) => prepared.get(name) ?? fallback;

    return {
        /** A given name for one person of `culture`, of sex "m" or "f", from `seed`. */
        given: (seed, culture, sex) => givenName(draws(streamOf(`${seed}:given`)), cultureOf(culture), sex),
        /** A family name (or byname) a household of `culture` might carry, from `seed`. */
        family: (seed, culture, context = {}) => lineName(draws(streamOf(`${seed}:family`)), cultureOf(culture), context).name,
        /** A whole name for someone outside any household (a pin's keeper, a stat block). */
        person: (seed, culture, sex) => stranger(`${seed}`, cultureOf(culture), sex).full,
        /**
         * Names every member of a household (given, sex, family and full name) in place, and
         * returns the household's shared name, where its convention gives one.
         */
        household: (seed, household) => nameHousehold(seed, household, cultureOf),
        cultureOf,
    };
}

/**
 * The convention a name base gives with every names setting on Automatic (N3: what the culture
 * inspector's Automatic reads), as the namer resolves it; an unknown base as Human Generic.
 * @param {string} nameBase
 * @returns {{form: string, order: string, lineage: string, wife: string}}
 */
export function conventionOf(nameBase) {
    const base = REAL_BASES[nameBase] ?? FANTASY_BASES[nameBase] ?? FANTASY_BASES["Human Generic"];
    return { form: base.form ?? "inherited", order: base.order ?? "given-first", lineage: base.lineage ?? "father", wife: base.wife ?? "takes" };
}

function prepare(culture, defaultMethod, places, near = []) {
    const baseName = REAL_BASES[culture.nameBase] || FANTASY_BASES[culture.nameBase] ? culture.nameBase : "Human Generic";
    const real = REAL_BASES[baseName];
    const fantasy = FANTASY_BASES[baseName];
    const base = real ?? fantasy;
    const user = culture.names ?? {};
    const own = user.lists ?? {};
    const userM = sanitiseList(own.m);
    const userF = sanitiseList(own.f);
    const userFamily = sanitiseList(own.family);

    let m = split(base.m);
    let f = split(base.f);
    if (base.blend) {
        m = base.blend.flatMap((b) => split(REAL_BASES[b].m).slice(0, 20));
        f = base.blend.flatMap((b) => split(REAL_BASES[b].f).slice(0, 20));
    }
    if (userM.length) m = userM;
    if (userF.length) f = userF;
    const family = userFamily.length ? userFamily : typeof base.family === "string" ? split(base.family) : [];
    const words = fantasy?.family?.words ? REAL_BASES[fantasy.family.words] : real;
    // The user's own lists are used as they are unless the culture asks for them to train a chain
    const methodFor = userM.length || userF.length ? (user.listUse === "train" ? "mix" : "list") : (user.method ?? base.method ?? defaultMethod);

    const [mMin, mMax] = fantasy ? [fantasy.min, fantasy.max] : lengthsOf(m);
    const [fMin, fMax] = fantasy ? [fantasy.min, fantasy.max] : lengthsOf(f);
    const chainBases = [
        { name: "m", i: 0, min: mMin, max: mMax, d: "", m: 0, b: m.filter((n) => SINGLE_WORD.test(n)).join(",") || "Ann" },
        { name: "f", i: 1, min: fMin, max: fMax, d: "", m: 0, b: f.filter((n) => SINGLE_WORD.test(n)).join(",") || "Ann" },
    ];
    return {
        name: culture.name,
        baseName,
        base,
        fantasy,
        words,
        settings: {
            form: user.form ?? base.form ?? "inherited",
            order: user.order ?? base.order ?? "given-first",
            lineage: user.lineage ?? base.lineage ?? "father",
            wife: user.wife ?? base.wife ?? "takes",
            familyFor: base.familyFor ?? "all",
        },
        method: methodFor,
        lists: { m, f, family },
        sets: { m: new Set(m), f: new Set(f) },
        weights: { m: rankWeights(m.length), f: rankWeights(f.length), family: rankWeights(family.length) },
        lengths: { m: [mMin, mMax], f: [fMin, fMax] },
        chain: new NamesGenerator(() => 0, chainBases),
        endings: fantasy ? { m: split(fantasy.endings.m), f: split(fantasy.endings.f) } : { m: commonEndings(m), f: commonEndings(f) },
        places,
        near,
        placeBase: Math.max(0, places.indexOf(baseName)),
        features: { m: split(words?.features?.m), f: split(words?.features?.f) },
        // Endings a name of this people may have: a generated name ending in a pair of consonants
        // none of them ends in was cut short by the chain
        syllables: { m: syllableCap(m), f: syllableCap(f) },
        // Whether names of two parts write the second in small letters (Korean Seong-gye)
        lowerAfterHyphen: [...m, ...f].some((n) => /-\p{Ll}/u.test(n)),
        finals: new Set([...m, ...f, ...(fantasy ? [...split(fantasy.endings.m), ...split(fantasy.endings.f)] : [])].map((n) => n.toLowerCase().slice(-2))),
    };
}

const syllables = (name) => (name.toLowerCase().match(/[aeiouyàáâãäåæèéêëìíîïòóôõöøùúûüýāēīōūœ]+/gu) ?? []).length;

/** The most vowel groups a name of the list has, but for the longest tenth. */
function syllableCap(list) {
    const counts = list.map(syllables).sort((a, b) => a - b);
    return counts.length ? Math.max(2, counts[Math.min(counts.length - 1, Math.floor(0.9 * counts.length))]) : 4;
}

/** Whether a generated name ends as names of its people do (not two consonants none ends with). */
function endsWell(name, C) {
    const tail = name.toLowerCase().slice(-2);
    return VOWEL.test(tail) || C.finals.has(tail);
}

/** A list's commonest endings (its last two or three letters, from the first vowel on). */
function commonEndings(list) {
    const counts = new Map();
    for (const name of list) {
        const tail = name.toLowerCase().slice(-3);
        const at = tail.search(VOWEL);
        const ending = at >= 0 ? tail.slice(at) : tail;
        counts.set(ending, (counts.get(ending) ?? 0) + 1);
    }
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10).map(([e]) => e);
}

/** Whether a generated given name is whole and readable. */
export function isCleanName(name, [min, max]) {
    return typeof name === "string" && name.length >= min && name.length <= max + 1 && SINGLE_WORD.test(name) && !TRIPLE.test(name.toLowerCase()) && VOWEL.test(name);
}

function givenName(d, C, sex) {
    const s = sex === "f" ? "f" : "m";
    const list = C.lists[s];
    const fromList = () => listName(d, list, C.weights[s]);
    switch (C.method) {
        case "list":
            return list.length ? fromList() : (chained(d, C, s) ?? "Ann");
        case "chain":
            return chained(d, C, s) ?? fromList();
        case "stem":
            return stemName(d, C, s) ?? stemName(d, C, s) ?? chained(d, C, s) ?? fromList();
        default:
            // mix: a real people's names mostly as they are, a share new; an invented people's
            // from its chain, a share from its own place names
            if (C.fantasy) return (d.chance(C.fantasy.stem) ? stemName(d, C, s) : null) ?? chained(d, C, s) ?? fromList();
            if (list.length && d.chance(NAMES.REAL_SHARE)) return fromList();
            return chained(d, C, s) ?? fromList();
    }
}

/**
 * A name from one of the culture's lists, by its weights, drawn again while it holds a common rude
 * word (NameFilter; an allowed name passes), up to RETRIES; then the first clean name on the list.
 * A list with no blocked name draws exactly as before.
 */
function listName(d, list, weights) {
    let name = d.weighted(list, weights);
    for (let attempt = 0; attempt < NAMES.RETRIES && isBlockedName(name); attempt++) name = d.weighted(list, weights);
    return isBlockedName(name) ? (list.find((entry) => !isBlockedName(entry)) ?? name) : name;
}

/** A name from the chain trained on the culture's list, checked whole and readable, and not blocked (NameFilter). */
function chained(d, C, s) {
    C.chain.rng = d.rng;
    for (let attempt = 0; attempt < NAMES.RETRIES; attempt++) {
        let name = C.chain.getBase(s === "f" ? 1 : 0);
        if (C.lowerAfterHyphen) name = name.replace(/-(\p{L})/u, (_, c) => `-${c.toLowerCase()}`);
        // A real base's chain should make new names: one already on the list is the list's
        if (!C.fantasy && C.sets[s].has(name)) continue;
        if (FAMOUS.has(name) || isBlockedName(name)) continue;
        if (!C.fantasy && syllables(name) > C.syllables[s]) continue;
        if (isCleanName(name, C.lengths[s]) && endsWell(name, C)) return name;
    }
    return null;
}

/** A given name from a stem of one of the culture's own place names and one of its endings. */
function stemName(d, C, s) {
    const place = placeWord(d, C);
    if (!place) return null;
    const lower = place.toLowerCase();
    const match = lower.match(/^[^aeiouy]*[aeiouy]+[^aeiouy]{0,2}/u);
    if (!match) return null;
    let stem = match[0];
    if (stem.length < 2) return null;
    const ending = d.pick(C.endings[s]);
    if (/[aeiouy]$/.test(stem) && /^[aeiouy]/.test(ending)) stem = stem.slice(0, -1);
    const name = stem.charAt(0).toUpperCase() + stem.slice(1) + ending;
    return isCleanName(name, C.lengths[s]) && !FAMOUS.has(name) && !isBlockedName(name) ? name : null;
}

/**
 * A whole place name of one word in the culture's place-name base, not blocked (NameFilter); `short`
 * for a byname, which carries a suffix and stands beside a given name.
 */
function placeWord(d, C, short = false) {
    const gen = C.places;
    gen.rng = d.rng;
    const longest = short ? Math.max(gen.nameBases[C.placeBase].max - 2, gen.nameBases[C.placeBase].min) : gen.nameBases[C.placeBase].max;
    const make = () => (short ? gen.getBaseShort(C.placeBase) : gen.getBase(C.placeBase));
    let name = make();
    for (let attempt = 0; attempt < NAMES.PLACE_RETRIES && (name.length >= longest - 1 || /[ '-]/.test(name) || isBlockedName(name)); attempt++) name = make();
    return /[ '-]/.test(name) || isBlockedName(name) ? null : name;
}

/**
 * A household's line name (family name, byname, clan or nomen), with the kind it is.
 * @param {{trade?: string, shares?: object}} context
 */
function lineName(d, C, { trade = null } = {}) {
    const { base, words, settings, lists } = C;
    if ((settings.form === "clan" || settings.form === "roman" || base.familyFrom === "list") && lists.family.length) return { name: listName(d, lists.family, C.weights.family), kind: "list" };
    if (settings.form === "clan" || settings.form === "roman") {
        if (lists.family.length) return { name: listName(d, lists.family, C.weights.family), kind: "list" };
        return { name: placeWord(d, C) ?? givenName(d, C, "m"), kind: "place" };
    }
    const own = TRADE_CONCEPT[trade];
    const tradeWords = Object.values(words?.trades ?? {});
    const ownWord = own ? words?.trades?.[own] : null;
    let shares;
    if (C.fantasy?.family && !C.fantasy.family.words) {
        shares = { place: C.fantasy.family.place ?? 1 };
    } else if (settings.form === "byname" || C.fantasy?.family?.words) {
        shares = { ...(C.fantasy?.family ?? NAMES.BYNAME) };
        delete shares.words;
        if (!ownWord && !C.fantasy) shares.trade = 0;
    } else {
        shares = { ...NAMES.INHERITED };
        if (!lists.family.length) shares.list = 0;
        if (!tradeWords.length) shares.trade = 0;
    }
    if (!C.features.m.length) shares.feature = 0;
    if (!base.father && !words?.father) shares.father = 0;
    const kind = d.share(shares) ?? "place";
    switch (kind) {
        case "list":
            return { name: listName(d, lists.family, C.weights.family), kind };
        case "trade": {
            if (ownWord && (settings.form === "byname" || d.chance(NAMES.OWN_TRADE))) return { name: ownWord, kind };
            if (tradeWords.length) return { name: d.pick(tradeWords), kind };
            break;
        }
        case "feature":
            return { name: d.pick(C.features.m), kind, feature: true };
        case "father": {
            const father = givenName(d, C, "m");
            return { name: patronymic(words?.father ? words : base, words === base ? C.baseName : "English", father, "m"), kind };
        }
        default:
            break;
    }
    // Half of the names from places come from places near this one, so the family is from
    // somewhere on the map; the rest from the culture's place names, as places further off
    const { place, nearby } = toponym(d, C);
    return { name: place ? fill(words?.place ?? "{p}", "p", place) : givenName(d, C, "m"), kind: "place", nearby };
}

/**
 * A place a family is named from: half the time a place near this one (when the namer was given
 * any), so the family comes from somewhere on the map, otherwise one of the culture's place names.
 */
function toponym(d, C) {
    if (C.near.length && d.chance(NAMES.NEARBY)) return { place: d.pick(C.near), nearby: true };
    return { place: placeWord(d, C, true), nearby: false };
}

/** A line name in its form for a person of `sex`. */
function lineFor(C, line, sex) {
    if (!line) return null;
    if (sex === "f") {
        if (line.feature && C.features.f.length) {
            const at = C.features.m.indexOf(line.name);
            if (at >= 0 && C.features.f[at]) return C.features.f[at];
        }
        return feminineFamily(C.baseName, line.name);
    }
    return line.name;
}

/** A clan name with its prefix for a person of `sex` (Ó, Mac, Ní, Nic). */
function clanFor(C, clan, sex, variant) {
    const forms = C.base.clan?.[sex === "f" ? "f" : "m"] ?? ["{c}"];
    return fill(forms[variant % forms.length], "c", clan);
}

/** Puts a person's name parts in the culture's order. */
function full(C, given, rest, { featureFirst = false } = {}) {
    const parts = rest.filter(Boolean);
    if (!parts.length) return given;
    if (C.settings.order === "family-first") return [...parts, given].join(" ");
    if (featureFirst) return [...parts, given].join(" ");
    return [given, ...parts].join(" ");
}

/** A person from outside the household, named as the head of a household of their own would be. */
function stranger(key, C, sex) {
    const d = draws(streamOf(`${key}:own`));
    const given = givenName(draws(streamOf(`${key}:given`)), C, sex);
    const { form } = C.settings;
    if (form === "patronymic") {
        let father = givenName(d, C, "m");
        if (father === given) father = givenName(d, C, "m");
        return { given, family: patronymic(C.base, C.baseName, father, sex), full: full(C, given, [patronymic(C.base, C.baseName, father, sex)]) };
    }
    if (form === "single") return { given, full: given };
    if (form === "clan") {
        const clan = lineName(d, C).name;
        const name = clanFor(C, clan, sex, Math.floor(d.rng() * 2));
        return { given, family: name, full: full(C, given, [name]) };
    }
    if (form === "roman") {
        const nomen = lineName(d, C);
        if (sex === "f") return { given: lineFor(C, nomen, "f"), family: lineFor(C, nomen, "f"), full: lineFor(C, nomen, "f") };
        return { given, family: nomen.name, full: `${given} ${nomen.name}` };
    }
    if (C.settings.familyFor === "wealth") return { given, full: given };
    let line = lineName(d, C);
    // A byname from a father of the person's own name reads as a mistake
    if (line.kind === "father" && line.name.startsWith(given)) line = lineName(d, C);
    const name = lineFor(C, line, sex);
    return { given, family: name, full: full(C, given, [name], { featureFirst: line.feature && C.base.featureFirst }) };
}

/** The sex of a member: by role where the household model sets it, otherwise even odds. */
function sexOf(member, key) {
    return member.sex ?? SEX_OF[member.role] ?? (streamOf(`${key}:sex`)() < 0.5 ? "m" : "f");
}

function nameHousehold(seed, household, cultureOf) {
    const C = cultureOf(household.culture);
    const d = draws(streamOf(`${seed}:line`));
    const members = household.members;
    members.forEach((m, j) => (m.sex = sexOf(m, `${seed}:m${j}`)));
    const head = members[0];
    // A household may be headed by a man or a woman: the spouse is a wife or a husband, and a
    // child is named from the parent the culture's lineage runs through
    const widowed = head.role === "widow, head" || head.role === "widower, head";
    const spouse = members.find((m) => m.role === "wife" || m.role === "husband");
    const oldFather = members.find((m) => m.role === "father");
    const oldMother = members.find((m) => m.role === "mother");
    const children = members.filter((m) => m.role === "child" || m.role === "grown child");
    const kinOwn = (j) => streamOf(`${seed}:m${j}:kin`)() < NAMES.KIN_OWN;

    // Given names first, each from the member's own stream
    members.forEach((m, j) => {
        const MC = m.culture ? cultureOf(m.culture) : C;
        m.given = givenName(draws(streamOf(`${seed}:m${j}:given`)), MC, m.sex);
    });
    // Brothers and sisters are not given the same name (a child may share a parent's)
    const taken = new Set();
    children.forEach((m) => {
        const j = members.indexOf(m);
        const MC = m.culture ? cultureOf(m.culture) : C;
        for (let k = 1; k <= 4 && taken.has(m.given); k++) m.given = givenName(draws(streamOf(`${seed}:m${j}:given:${k}`)), MC, m.sex);
        taken.add(m.given);
    });
    // Those who bring their own name are named as strangers, in their own culture
    members.forEach((m, j) => {
        const isKin = m.role === "kinsman" || m.role === "kinswoman";
        if (OWN.has(m.role) || m.culture || (isKin && kinOwn(j))) {
            const MC = m.culture ? cultureOf(m.culture) : C;
            const named = stranger(`${seed}:m${j}`, MC, m.sex);
            m.given = named.given;
            m.family = named.family ?? null;
            m.full = named.full;
            m.own = true;
        }
    });
    const line = members.filter((m) => !m.own);
    const { form, lineage, wife: wifeRule } = C.settings;
    const lineSex = lineage === "mother" ? "f" : "m";
    // The parent a child is named from: the head or the spouse of the lineage's sex; for a widowed
    // or single head of the other sex, the late spouse
    const lineParent = [head, spouse].find((p) => p && !p.own && p.sex === lineSex) ?? null;
    const oldLineParent = lineSex === "f" ? oldMother : oldFather;
    const oldOtherParent = lineSex === "f" ? oldFather : oldMother;
    let shared = null;

    if (form === "patronymic") {
        const headFather = oldLineParent && !oldLineParent.own ? oldLineParent.given : givenName(d, C, lineSex);
        const childParent = lineParent ? lineParent.given : givenName(d, C, lineSex);
        let extra = null;
        if (C.base.father?.rule === "castilian" && d.chance(NAMES.IBERIAN_PLACE)) {
            const { place } = toponym(d, C);
            if (place) extra = { name: fill(C.base.place, "p", place) };
        }
        if (NAMES.ALSO_FAMILY[C.baseName] && d.chance(NAMES.ALSO_FAMILY[C.baseName]) && C.lists.family.length) extra = { name: listName(d, C.lists.family, C.weights.family) };
        if (C.baseName === "Arabic" && d.chance(NAMES.ARABIC_LAQAB)) {
            const concept = TRADE_CONCEPT[household.trade];
            const word = concept ? C.base.trades[concept] : null;
            const place = word ? null : toponym(d, C).place;
            extra = word ? { name: word } : place ? { name: fill(C.base.place, "p", place) } : null;
        }
        const patro = (parent, sex) => patronymic(C.base, C.baseName, parent, sex);
        for (const m of line) {
            let parent;
            if (m === head) parent = headFather;
            else if (m.role === "child" || m.role === "grown child") parent = childParent;
            // Kin near the head's age are taken as his brothers and sisters; the rest are uncles,
            // aunts and cousins with fathers of their own
            else if ((m.role === "kinsman" || m.role === "kinswoman") && Math.abs(m.age - head.age) <= 15) parent = headFather;
            else parent = givenName(draws(streamOf(`${seed}:${m.role}:father`)), C, lineSex);
            // No one is named for a parent of their own name, but a child may share a parent's
            if (parent === m.given && m !== head && m.role !== "child" && m.role !== "grown child") parent = givenName(draws(streamOf(`${seed}:${m.role}:father:2`)), C, lineSex);
            if (parent === m.given && m === head && !oldLineParent) parent = givenName(draws(streamOf(`${seed}:head:father:2`)), C, lineSex);
            // A matronymic is formed from the mother's name by the same rules
            const parts = [patro(parent, m.sex)];
            const inLine = m === head || m.role === "child" || m.role === "grown child" || m.role === "kinsman" || m.role === "kinswoman" || m === oldLineParent;
            if (extra && inLine) parts.push(m.sex === "f" ? feminineFamily(C.baseName, extra.name) : extra.name);
            m.family = parts.join(" ");
            m.full = full(C, m.given, parts);
        }
        if (oldLineParent && !oldLineParent.own) oldLineParent.full = full(C, oldLineParent.given, oldLineParent.family.split(" "));
        shared = extra?.name ?? null;
    } else if (form === "single") {
        for (const m of line) {
            m.family = null;
            m.full = m.given;
        }
        if (d.chance(NAMES.SINGLE_BYNAME) && !head.own) {
            const by = C.base.father && !C.fantasy ? patronymic(C.base, C.baseName, givenName(d, C, "m"), head.sex) : C.features.m.length ? d.pick(C.features.m) : null;
            if (by) head.full = full(C, head.given, [by]);
        }
    } else if (form === "roman") {
        const nomen = lineName(d, C);
        const cognomen = C.features.m.length && d.chance(0.7) ? { name: d.pick(C.features.m), feature: true } : null;
        shared = nomen.name;
        const daughters = children.filter((m) => m.sex === "f" && !m.own).sort((a, b) => b.age - a.age);
        // A spouse and the head's other parent bring their own nomen; children take their
        // father's (the head's, or the spouse's where the head is the mother)
        const spouseNomen = spouse && !spouse.own ? lineName(draws(streamOf(`${seed}:spouse:nomen`)), C) : null;
        const childNomen = lineParent === spouse && spouseNomen ? spouseNomen : nomen;
        const ordinals = daughters.length === 2 ? ["Maior", "Minor"] : ["Prima", "Secunda", "Tertia", "Quarta", "Quinta", "Sexta", "Septima", "Octavia"];
        for (const m of line) {
            const ownLine = m === spouse ? spouseNomen : m === oldOtherParent ? lineName(draws(streamOf(`${seed}:${m.role}:nomen`)), C) : m.role === "child" || m.role === "grown child" ? childNomen : nomen;
            if (m.sex === "f") {
                const fem = lineFor(C, ownLine, "f");
                const at = daughters.indexOf(m);
                const tail = daughters.length > 1 && at >= 0 ? ordinals[at] : cognomen && ownLine === nomen ? lineFor(C, cognomen, "f") : null;
                m.given = fem;
                m.family = fem;
                m.full = tail ? `${fem} ${tail}` : fem;
            } else {
                m.family = ownLine.name;
                m.full = [m.given, ownLine.name, ownLine === nomen ? cognomen?.name : null].filter(Boolean).join(" ");
            }
        }
    } else {
        // inherited, byname and clan: one line name for the household
        const noFamily = C.settings.familyFor === "wealth" && (household.wealth === "poor" || household.wealth === "modest");
        const lineOf = form === "clan" ? lineName(d, C) : lineName(d, C, { trade: household.trade });
        const variant = Math.floor(d.rng() * 2);
        const nameFor = (l, sex, v = variant) => (form === "clan" ? clanFor(C, l.name, sex, v) : lineFor(C, l, sex));
        // The line is the head's; a spouse takes it or keeps their own, and children take the line
        // of the parent the lineage runs through (a late spouse's, where the head was widowed)
        const spouseLine = wifeRule === "keeps" && spouse ? lineName(d, C) : lineOf;
        const lateLine = !lineParent && wifeRule === "keeps" && (widowed || head.sex !== lineSex) ? lineName(draws(streamOf(`${seed}:late:line`)), C) : lineOf;
        const childLine = lineParent === spouse && spouse ? spouseLine : lineParent === head ? lineOf : lateLine;
        shared = noFamily ? null : nameFor(lineOf, "m");
        household.nameKind = noFamily ? null : lineOf.kind;
        household.nameNearby = !noFamily && !!lineOf.nearby;
        for (const m of line) {
            let l = lineOf;
            if (m === spouse) l = spouseLine;
            else if (m === oldOtherParent && wifeRule === "keeps") l = lineName(draws(streamOf(`${seed}:${m.role}:line`)), C);
            if (m.role === "child" || m.role === "grown child") l = childLine;
            if (noFamily) {
                m.family = null;
                m.full = m.given;
                continue;
            }
            const name = nameFor(l, m.sex, l === lineOf ? variant : 0);
            m.family = name;
            m.full = full(C, m.given, [name], { featureFirst: l.feature && C.base.featureFirst });
        }
    }
    household.name = shared;
    return shared;
}

/** A random source in [0, 1) for a key: the kernel's mulberry32 seeded by the key's hash. */
function streamOf(key) {
    return mulberry32(hashString(key));
}

/** Helpers over a random source. */
function draws(rng) {
    return {
        rng,
        chance: (p) => rng() < p,
        pick: (list) => list[Math.floor(rng() * list.length)],
        /** A pick from a list weighted by `cumulative` (its running weights). */
        weighted: (list, cumulative) => {
            const target = rng() * cumulative[cumulative.length - 1];
            let lo = 0;
            let hi = cumulative.length - 1;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (cumulative[mid] > target) hi = mid;
                else lo = mid + 1;
            }
            return list[lo];
        },
        /** A key of `shares` ({key: weight}) by weight; null if none has weight. */
        share: (shares) => {
            const entries = Object.entries(shares).filter(([, w]) => w > 0);
            const total = entries.reduce((a, [, w]) => a + w, 0);
            if (!total) return null;
            let t = rng() * total;
            for (const [k, w] of entries) if ((t -= w) < 0) return k;
            return entries[entries.length - 1][0];
        },
    };
}

/** Running weights for a list ordered most common first: the name at rank r weighs 1/(r + 3). */
function rankWeights(length, offset = 3) {
    const cumulative = new Float64Array(length);
    let sum = 0;
    for (let r = 0; r < length; r++) cumulative[r] = sum += 1 / (r + offset);
    return cumulative;
}
